model:
rachana: 1
sutra: fx-scenario
version: 1
description: 
match: { kind: fx-scenario, priority: 10 }
title: { pill: "Market risk · Scenario FX", id: "$.FX_SCENARIO_ID", with: "$.CURRENCY" }
strip:
  - { label: "Currency", bind: "$.CURRENCY", emphasis: true }
  - { label: "Quote", bind: "$.QUOTE" }
  - { label: "Rate today", bind: "$.RATE", emphasis: true }
  - { label: "Business date", bind: "$.BUSINESS_DATE" }
  - { label: "Scenario set", bind: "link($.SCENARIO_SET_ID, 'scenario-set')" }
  - { label: "Source", bind: "$.SOURCE" }
panels:
  - id: rates-chart
    kind: line
    title: "Rate under each scenario day (USD per unit)"
    key: "F2"
    code: "CHART"
    values: "$.RATES"
    labels: "$src.SCENARIO_DATES"
  - id: rates
    kind: table
    title: "Rates by scenario day (change against today's rate)"
    key: "F3"
    code: "RATES"
    rows: "$.RATES"
    limit: 30
    columns:
      - { label: "Index i", bind: "#index" }
      - { label: "Scenario day", bind: "$src.SCENARIO_DATES[#index]" }
      - { label: "Rate", bind: "@" }
      - { label: "Change vs today (%)", bind: "(@ - $.RATE) / $.RATE * 100", fmt: "signed2", tone: "sign" }
  - id: note
    kind: markdown
    title: "How to read it"
    area: right
    phone: { tier: "more", from: "fragment" }
    text: "Index i is the position of the rate in RATES and of the day in the scenario set ${$.SCENARIO_SET_ID}: the same position in every P&L vector and scenario PV of ${$.BUSINESS_DATE}. Change is in percent of today's rate."
  - id: built
    kind: provenance
    title: "How this view was built"
    phone: { tier: "more", from: "fragment" }
  - id: refs
    kind: links
    title: "Linked entities"
    code: "REFS"
    area: right
    phone: { tier: "more", from: "fragment" }
keys: { F7: "link($.SCENARIO_SET_ID, 'scenario-set')", F9: "raw" }
